SELECT name FROM cinemas WHERE name LIKE 'UTE Demo%';
SELECT COUNT(*) AS demo_future_showtimes FROM showtimes s JOIN rooms r ON r.id=s.room_id WHERE r.name LIKE 'Demo %' AND s.start_time>NOW();